widget_set_width(w, 640);
widget_set_height(w, 480);      /* nothing to chain past an error */

/* preferred: named, defaulted configuration */
widget_cfg cfg = { .width = 640, .height = 480, .title = "Sample widget" };
widget_t *w2 = widget_new(&cfg);
